import{_ as a,o as n,c as e,a6 as t}from"./chunks/framework.BrkgobfX.js";const b=JSON.parse('{"title":"日志","description":"log_format 的可用变量、缓冲与条件日志、access_log 的数组继承，以及一份可排障的日志格式。","frontmatter":{"title":"日志","description":"log_format 的可用变量、缓冲与条件日志、access_log 的数组继承，以及一份可排障的日志格式。","source":"https://daiw.org/manual/nginx/logging"},"headers":[],"relativePath":"manual/tools/nginx/logging.md","filePath":"manual/tools/nginx/logging.md"}'),p={name:"manual/tools/nginx/logging.md"};function o(l,s,r,i,c,d){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to &quot;日志&quot;">​</a></h1><h2 id="access-log" tabindex="-1">access_log <a class="header-anchor" href="#access-log" aria-label="Permalink to &quot;access\\_log&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    access_log path [format [buffer=size] [gzip[=level]]</span></span>
<span class="line"><span>                          [flush=time] [if=condition]];</span></span>
<span class="line"><span>         access_log off;</span></span>
<span class="line"><span>默认:    access_log logs/access.log combined;</span></span>
<span class="line"><span>上下文:  http, server, location, if in location, limit_except</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>关闭日志用 <code>access_log off;</code></strong>——注意与 <a href="/Front2Full/manual/tools/nginx/core-module"><code>error_log</code></a> 不同，后者的 <code>off</code> 会被当成文件名。</p><p><strong><code>access_log</code> 是<a href="/Front2Full/manual/tools/nginx/contexts">数组型指令</a>。</strong> 在 location 里写了一条，server 级的全部失效。</p><p>这会造成「某些路径的日志突然不见了」——尤其是为某个 location 单独加日志时，很容易把主日志弄丢。</p><h2 id="log-format" tabindex="-1">log_format <a class="header-anchor" href="#log-format" aria-label="Permalink to &quot;log\\_format&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    log_format name [escape=default|json|none] string ...;</span></span>
<span class="line"><span>上下文:  http</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>内置的 <code>combined</code> 格式：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>log_format combined &#39;$remote_addr - $remote_user [$time_local] &#39;</span></span>
<span class="line"><span>                    &#39;&quot;$request&quot; $status $body_bytes_sent &#39;</span></span>
<span class="line"><span>                    &#39;&quot;$http_referer&quot; &quot;$http_user_agent&quot;&#39;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这是 Apache combined 格式的复刻，工具链兼容性好，但<strong>信息严重不足</strong>——排查性能问题时它什么也告诉不了你。</p><h3 id="一份可排障的格式" tabindex="-1">一份可排障的格式 <a class="header-anchor" href="#一份可排障的格式" aria-label="Permalink to &quot;一份可排障的格式&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>log_format main escape=json</span></span>
<span class="line"><span>    &#39;{&quot;time&quot;:&quot;$time_iso8601&quot;,&#39;</span></span>
<span class="line"><span>    &#39;&quot;remote_addr&quot;:&quot;$remote_addr&quot;,&#39;</span></span>
<span class="line"><span>    &#39;&quot;request&quot;:&quot;$request&quot;,&#39;</span></span>
<span class="line"><span>    &#39;&quot;uri&quot;:&quot;$request_uri&quot;,&#39;</span></span>
<span class="line"><span>    &#39;&quot;status&quot;:$status,&#39;</span></span>
<span class="line"><span>    &#39;&quot;bytes&quot;:$body_bytes_sent,&#39;</span></span>
<span class="line"><span>    &#39;&quot;referer&quot;:&quot;$http_referer&quot;,&#39;</span></span>
<span class="line"><span>    &#39;&quot;ua&quot;:&quot;$http_user_agent&quot;,&#39;</span></span>
<span class="line"><span>    &#39;&quot;xff&quot;:&quot;$http_x_forwarded_for&quot;,&#39;</span></span>
<span class="line"><span>    &#39;&quot;host&quot;:&quot;$host&quot;,&#39;</span></span>
<span class="line"><span>    &#39;&quot;request_time&quot;:$request_time,&#39;</span></span>
<span class="line"><span>    &#39;&quot;upstream_addr&quot;:&quot;$upstream_addr&quot;,&#39;</span></span>
<span class="line"><span>    &#39;&quot;upstream_status&quot;:&quot;$upstream_status&quot;,&#39;</span></span>
<span class="line"><span>    &#39;&quot;upstream_response_time&quot;:&quot;$upstream_response_time&quot;,&#39;</span></span>
<span class="line"><span>    &#39;&quot;upstream_connect_time&quot;:&quot;$upstream_connect_time&quot;,&#39;</span></span>
<span class="line"><span>    &#39;&quot;cache&quot;:&quot;$upstream_cache_status&quot;}&#39;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><p>关键字段的意义：</p><table tabindex="0"><thead><tr><th>字段</th><th>为什么要记</th></tr></thead><tbody><tr><td><code>$request_uri</code></td><td><strong>原始 URI</strong>——<code>$request</code> 里的路径会被<a href="/Front2Full/manual/tools/nginx/variables">内部重定向改写</a></td></tr><tr><td><code>$request_time</code></td><td>总耗时（<strong>含读客户端请求体</strong>）</td></tr><tr><td><code>$upstream_response_time</code></td><td>上游耗时。<code>$request_time</code> 减它 = nginx + 网络开销</td></tr><tr><td><code>$upstream_connect_time</code></td><td>建连耗时。持续偏高说明上游连接池或网络有问题</td></tr><tr><td><code>$upstream_addr</code></td><td>实际打到哪台。<strong>重试过会是列表</strong></td></tr><tr><td><code>$upstream_status</code></td><td>上游返回码。与 <code>$status</code> 不同说明 nginx 做了转换</td></tr><tr><td><code>$upstream_cache_status</code></td><td><a href="/Front2Full/manual/tools/nginx/caching">缓存命中情况</a></td></tr><tr><td><code>$http_x_forwarded_for</code></td><td>代理链</td></tr></tbody></table><h3 id="escape-参数" tabindex="-1">escape 参数 <a class="header-anchor" href="#escape-参数" aria-label="Permalink to &quot;escape 参数&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>log_format main escape=json &#39;...&#39;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>三个值：</p><table tabindex="0"><thead><tr><th>值</th><th>行为</th></tr></thead><tbody><tr><td><code>default</code></td><td>转义 <code>&quot;</code>、<code>\\</code> 与不可见字符为 <code>\\xXX</code></td></tr><tr><td><code>json</code></td><td>按 <strong>JSON 规则</strong>转义</td></tr><tr><td><code>none</code></td><td><strong>不转义</strong>——危险</td></tr></tbody></table><p><strong>输出 JSON 格式的日志必须用 <code>escape=json</code></strong>，否则 User-Agent 里的引号会破坏 JSON 结构，导致整行无法解析。</p><p><code>escape=none</code> 允许日志注入——攻击者可以在 URI 或 UA 里塞换行伪造日志行。<strong>不要用</strong>。</p><h2 id="缓冲与压缩" tabindex="-1">缓冲与压缩 <a class="header-anchor" href="#缓冲与压缩" aria-label="Permalink to &quot;缓冲与压缩&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>access_log /var/log/nginx/access.log main buffer=64k flush=5s;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>buffer=size</code></td><td>攒够这么多再写盘</td></tr><tr><td><code>flush=time</code></td><td>最多攒这么久</td></tr><tr><td><code>gzip[=level]</code></td><td><strong>边写边压缩</strong></td></tr></tbody></table><p>高流量站点必配缓冲——每条日志一次 <code>write()</code> 系统调用是可观的开销。</p><p><code>gzip</code> 需要日志文件不被外部程序实时读取（压缩流不可中途追加读）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>access_log /var/log/nginx/access.log.gz main gzip=5 buffer=64k flush=5s;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>带缓冲时，日志不是实时的。</strong> 调试时看不到刚发的请求属正常现象——要么等 <code>flush</code> 时间到，要么临时去掉 buffer 参数。</p><h2 id="条件日志" tabindex="-1">条件日志 <a class="header-anchor" href="#条件日志" aria-label="Permalink to &quot;条件日志&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map $status $loggable {</span></span>
<span class="line"><span>    ~^[23]  0;      # 2xx/3xx 不记</span></span>
<span class="line"><span>    default 1;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>access_log /var/log/nginx/error-only.log main if=$loggable;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><code>if=</code> 的值为空或 <code>&quot;0&quot;</code> 时<strong>不记录</strong>。</p><p>实用场景：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 健康检查不污染日志</span></span>
<span class="line"><span>map $request_uri $log_it {</span></span>
<span class="line"><span>    /healthz 0;</span></span>
<span class="line"><span>    /metrics 0;</span></span>
<span class="line"><span>    default  1;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>access_log /var/log/nginx/access.log main if=$log_it;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>高流量下这能显著减少日志量——健康检查往往占了请求数的大头。</p><h2 id="记录请求体" tabindex="-1">记录请求体 <a class="header-anchor" href="#记录请求体" aria-label="Permalink to &quot;记录请求体&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>log_format postdata &#39;$remote_addr [$time_local] &quot;$request&quot; $request_body&#39;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>$request_body</code> 只在请求体<strong>被读进内存</strong>时才有值——即经过了 <code>proxy_pass</code>/<code>fastcgi_pass</code> 且没有写进临时文件。大请求体会是空的。</p><p><strong>记录请求体有隐私与合规风险</strong>：密码、令牌、个人信息都会进日志。只在调试时临时开启，且注意日志文件的访问权限与保留期。</p><h2 id="syslog" tabindex="-1">syslog <a class="header-anchor" href="#syslog" aria-label="Permalink to &quot;syslog&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>access_log syslog:server=10.0.0.1:514,facility=local7,tag=nginx,severity=info main;</span></span>
<span class="line"><span>error_log  syslog:server=unix:/dev/log,tag=nginx warn;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>日志送 syslog 而非本地文件，适合集中式日志采集。支持 UDP、TCP（<code>server=</code> 前加 <code>tcp:</code>）与本地 UNIX 套接字。</p><h2 id="轮转" tabindex="-1">轮转 <a class="header-anchor" href="#轮转" aria-label="Permalink to &quot;轮转&quot;">​</a></h2><p>nginx <strong>不自带日志轮转</strong>，靠外部工具（logrotate）+ 信号：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>postrotate</span></span>
<span class="line"><span>    /bin/kill -USR1 $(cat /var/run/nginx.pid)</span></span>
<span class="line"><span>endscript</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><code>USR1</code> 让 nginx <strong>重新打开日志文件</strong>。流程是：logrotate 先 <code>mv</code> 走旧文件（nginx 仍持有其 fd，继续写），再发 <code>USR1</code>，nginx 关闭旧 fd 打开新文件。</p><p><strong>漏发 <code>USR1</code> 会导致 nginx 一直往被 <code>mv</code> 走（甚至已删除）的文件里写</strong>——表现是新日志文件永远是空的，磁盘却在涨。这是日志轮转的经典故障。</p><p><code>logrotate</code> 的 <code>copytruncate</code> 选项可以避免这个问题（复制后清空原文件），但会在复制窗口内丢日志，且对大文件开销高。<strong>优先用 <code>USR1</code> 方案</strong>。</p><h2 id="完整配置" tabindex="-1">完整配置 <a class="header-anchor" href="#完整配置" aria-label="Permalink to &quot;完整配置&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http {</span></span>
<span class="line"><span>    log_format main escape=json</span></span>
<span class="line"><span>        &#39;{&quot;time&quot;:&quot;$time_iso8601&quot;,&quot;remote_addr&quot;:&quot;$remote_addr&quot;,&#39;</span></span>
<span class="line"><span>        &#39;&quot;method&quot;:&quot;$request_method&quot;,&quot;uri&quot;:&quot;$request_uri&quot;,&#39;</span></span>
<span class="line"><span>        &#39;&quot;status&quot;:$status,&quot;bytes&quot;:$body_bytes_sent,&#39;</span></span>
<span class="line"><span>        &#39;&quot;rt&quot;:$request_time,&quot;urt&quot;:&quot;$upstream_response_time&quot;,&#39;</span></span>
<span class="line"><span>        &#39;&quot;uaddr&quot;:&quot;$upstream_addr&quot;,&quot;cache&quot;:&quot;$upstream_cache_status&quot;,&#39;</span></span>
<span class="line"><span>        &#39;&quot;host&quot;:&quot;$host&quot;,&quot;ua&quot;:&quot;$http_user_agent&quot;,&quot;xff&quot;:&quot;$http_x_forwarded_for&quot;}&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    map $request_uri $log_it {</span></span>
<span class="line"><span>        /healthz 0;</span></span>
<span class="line"><span>        default  1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    access_log /var/log/nginx/access.log main</span></span>
<span class="line"><span>               buffer=64k flush=5s if=$log_it;</span></span>
<span class="line"><span>    error_log  /var/log/nginx/error.log warn;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p>下一篇：<a href="/Front2Full/manual/tools/nginx/rewrite">rewrite、return 与 if</a>。</p>`,50)])])}const m=a(p,[["render",o]]);export{b as __pageData,m as default};
